FUNCTION_BLOCK FB_Conveyor
VAR_INPUT
    bEnable : BOOL;
    bReset : BOOL;
END_VAR
VAR_OUTPUT
    bRunning : BOOL;
    bError : BOOL;
END_VAR
VAR
    nStep : INT;
    tonStart : TON;
    tonWatchdog : TON;
END_VAR
tonWatchdog(IN := (nStep = 20) AND bEnable, PT := T#30S);

CASE nStep OF
    0:
        IF bEnable THEN
            nStep := 10;
        END_IF;

    10:
        tonStart(IN := TRUE, PT := T#2S);
        IF tonStart.Q THEN
            bRunning := TRUE;
            nStep := 20;
        END_IF;

    20:
        IF NOT bEnable THEN
            bRunning := FALSE;
            nStep := 0;
        ELSIF tonWatchdog.Q THEN
            bRunning := FALSE;
            bError := TRUE;
            nStep := 900;
        END_IF;

    900:
        IF bReset AND NOT bEnable THEN
            bError := FALSE;
            nStep := 0;
        END_IF;
END_CASE;

